from pathlib import Path
from flask import Flask, request

app = Flask(__name__)
TMP = Path("/tmp/host-import")

def file_path(file_id):
    return TMP / ("%s.csv" % file_id)

@app.post("/import")
def upload():
    file_id = request.form["file_id"]
    path = file_path(file_id)
    path.write_text(request.form["csv"])
    return {"ok": True, "size": len(path.read_text())}
